window.RP_SESSION={"id":"S-e264ab85cc7d","messages":[{"id":"RP-0001370","time":"2025-11-08T01:20:00+09:00","room":"RP","name":"마헌 아이코","profile":"알트 본젠","identity":"reviewed","type":"dialogue","body":"[마헌 아이코]\n해골이 된 아저씨가 저에게 뿔을 주면서 무기를 만들어 달라고 하셨어요! 오랜만에 보는 아저씨가 보수도 두둑하게 주겠다고 하셨으니 최선을 다해봐야죠!\n\n첫번째는 한손검이에요! 가장 무난하면서도 대장장이의 실력을 가장 잘 엿볼수 있는 무기죠. 아저씨는 무기 본연의 특기만 잘 스며들면 된다고 했으니 시작해봐요!\n\n우선 톱을 이용해 와이번 뿔을 2개로 나눕니다. 그리고 뿔 내부에 있을수도 있는 수분이 도구를 썩힐수 있으니 바짝 말려 수분을 없애요. 그리고 그 사이 재료를 모아 놓는데 화염 내성이 강한 레드 우드와 볼가노스의 가죽, 화염의 마석을 준비해요.\n\n이제 다 말랐을 뼈에 흑연으로 검의 모양을 표시해줍니다. 코등이와 검날이 이어지는 디자인으로 아저씨가 좋아하는 야성적인 이미지를 강화하는거에요. 전부 표시를 해주고 큰 부분은 톱으로 잘라내고 나머지 세세한 부분은 아저씨가 예전에 사준 패달을 밟으면 회전하는 그라인더라는걸 써서 갈아주며 물에 불린 숫돌도 가져와 날카롭게 만","characters":["P-252eb800bab0"]},{"id":"RP-0001371","time":"2025-11-08T01:20:00+09:00","room":"RP","name":"마헌 아이코","profile":"알트 본젠","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-252eb800bab0"]},{"id":"RP-0001372","time":"2025-11-08T01:20:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"쓰라린 실패, 운명을 목도하십시오.","characters":[]},{"id":"RP-0001373","time":"2025-11-08T01:21:00+09:00","room":"RP","name":"마헌 아이코","profile":"알트 본젠","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-252eb800bab0"]},{"id":"RP-0001374","time":"2025-11-08T01:21:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"훌륭한 성공, 당신은 운명의 바람을 탑니다.","characters":[]},{"id":"RP-0001375","time":"2025-11-08T01:25:00+09:00","room":"RP","name":"마헌 아이코","profile":"알트 본젠","identity":"reviewed","type":"dialogue","body":"[와이혼 소드]\n와이번의 뿔로 만든 검으로 절삭력은 일반적인 철검 수준이지만 검신에서 얼마든 불과 같은 고열을 내뿜을수 있다.","characters":["P-252eb800bab0"]},{"id":"RP-0001376","time":"2025-11-08T01:44:00+09:00","room":"RP","name":"마헌 아이코","profile":"알트 본젠","identity":"reviewed","type":"dialogue","body":"[마헌 아이코]\n이번엔 아저씨의 동료라는 분이 필요하다고 하신 워픽? 아무튼 곡괭이를 의뢰받았어요! 그분이 와이번을 아주 그냥 끝장냈다고 하시던데 그런 분이라면 이 무기와 공명을 일으킬 가능성이 있겠어요!\n\n먼저 남은 뿔과 용염철과 남은 볼가노스의 가죽, 그리고 화염과 땅의 마석을 준비해요!\n\n검 때와는 다르게 이번엔 철을 주조해야해서 미리 제 몸에 화염 내성 인첸트를 걸고 시작할게요! 용광로에 석탄과 바람울 집어넣으며 열을 올려요. 1100...1250...1300! 용염철은 1300도부터 녹으니 이걸 용광로에 넣고 기다려요.\n\n기다리는 동안 검때와 똑같이 흑연으로 곡괭이 날부분과 손잡이와 이어지는 곳까지 표시한 다음 톱과 그라인더로 잘라요. 이번에는 곡괭이니 굳이 숫돌질을 세세하게 할 필요 없이 적당히 매끄럽게만 만들어줘요.\n\n이제 다 녹은 용염철을 거푸집에 넣은 다음 남은 용염철을 살짝 식혀 손잡이에 이어 고정해줄 앵커로 만듭니다! 그리고 거푸집으로 만든 용염철 손잡이에는 홈이","characters":["P-252eb800bab0"]},{"id":"RP-0001377","time":"2025-11-08T01:49:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"unresolved","type":"dialogue","body":"!운명","characters":[]},{"id":"RP-0001378","time":"2025-11-08T01:49:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"훌륭한 성공, 당신은 운명의 바람을 탑니다.","characters":[]},{"id":"RP-0001379","time":"2025-11-08T01:49:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"unresolved","type":"dialogue","body":"!운명","characters":[]},{"id":"RP-0001380","time":"2025-11-08T01:49:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"훌륭한 성공, 당신은 운명의 바람을 탑니다.","characters":[]},{"id":"RP-0001381","time":"2025-11-08T01:49:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"unresolved","type":"dialogue","body":"!운명","characters":[]},{"id":"RP-0001382","time":"2025-11-08T01:49:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명의 영향을 받고있지 않습니다.","characters":[]},{"id":"RP-0001383","time":"2025-11-08T01:53:00+09:00","room":"RP","name":"본문 밖 반응","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"*사기아님?","characters":[]},{"id":"RP-0001384","time":"2025-11-08T01:57:00+09:00","room":"RP","name":"마헌 아이코","profile":"알트 본젠","identity":"reviewed","type":"dialogue","body":"[역작: 영웅의 와이혼 워 픽]\n오직 영웅같은 용병에게만 공명을 하는 워 픽이다.\n관통력, 내구성 모두 최고 수준이며 곡괭이의 날 부분에서 용광로의 초염 수준의 초고열을 내뿜을수 있다.\n단 한번 워 픽으로 막아내는 모든 공격을 무효화 할수 있다.","characters":["P-252eb800bab0"]},{"id":"RP-0001385","time":"2025-11-08T01:57:00+09:00","room":"RP","name":"마헌 아이코","profile":"알트 본젠","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-252eb800bab0"]},{"id":"RP-0001386","time":"2025-11-08T01:58:00+09:00","room":"RP","name":"마헌 아이코","profile":"알트 본젠","identity":"reviewed","type":"dialogue","body":"\"어, 어, 어...역작...입니다.\"","characters":["P-252eb800bab0"]}]};
